## Changes

The goal of this PR is to add an extension point so that users may build their own to solution for what #757 is trying to solve.

User is asking to be able to customize the column names based on the category name. What I did is introduce an interface + option so that users may inject whatever code they want into the resolution. Category name is a bit fuzzy, so I built it based on the final table name which is close, but not the same. Category names get sanitized and may be changed based on mapping rules.

Example:

```csharp
            using var loggerFactory = LoggerFactory.Create(loggingBuilder => loggingBuilder
                .AddOpenTelemetry(builder=>
                {
                    builder.AddGenevaLogExporter(options =>
                    {
                        options.ConnectionString = "EtwSession=OpenTelemetry";
                        options.TableNameMappings = new Dictionary<string, string> { ["*"] = "*" };
                        options.TableColumnNameResolver = new TableColumnNameResolver();
                    });
                })

    internal sealed class TableColumnNameResolver : IGenevaTableColumnNameResolver
    {
        public const string CustomTable1 = "CustomTable1";
        public const string CustomTable2 = "CustomTable2";

        private readonly ISet<string> customTable1ColumnNames = new HashSet<string>
        {
            "name",
            "code",
            "status",
        };

        private readonly ISet<string> customTable2ColumnNames = new HashSet<string>
        {
            "responseCode",
            "errorMessage",
        };

        public ISet<string> ResolveColumnNamesForTableName(string tableName)
        {
            if (tableName.Equals(CustomTable1, StringComparison.OrdinalIgnoreCase))
            {
                return this.customTable1ColumnNames;
            }

            if (tableName.Equals(CustomTable2, StringComparison.OrdinalIgnoreCase))
            {
                return this.customTable2ColumnNames;
            }

            // Fallback to default behavior which is to use options.CustomFields.
            return null;
        }
    }
```

